SELECT (SELECT count(*) FROM t_content) AS ordinary_rows, (SELECT count(*) FROM t0_content) AS content_rows, (SELECT count(*) FROM t0_content WHERE docid=0 AND c0col0 IS NULL AND c1col1 IS NULL AND c2col2 IS NULL AND c3col3 IS NULL) AS matching_content_rows, (SELECT count(*) FROM t0_segdir) AS segdir_rows, (SELECT count(*) FROM t0_segdir WHERE level=0 AND idx=0 AND start_block=0 AND leaves_end_block=0 AND end_block='0 42' AND hex(root)='000131030102000103323334050101010200000461616161050101020200000462626262050101030200') AS matching_segdir_rows;